PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <https://example.com/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?s ?label ?p ?uri
WHERE {
  ?s a brick:Zone ;
     rdfs:label ?label .
  FILTER (STR(?label) = "DataCenter_top_ZN_6")
  ?p ref:hasExternalReference ?s .
  ?p ref:hasTimeseriesId ?uri .
  OPTIONAL { ?c a brick:Class . }
}
ORDER BY ?uri

PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <https://example.com/ref#>
SELECT ?sensor ?label ?tp ?sid
WHERE {
  ?sensor brick:hasLocation http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z09 .
  ?tp a brick:Class .
  ?sensor a ?tp .
  OPTIONAL {
    ?point ref:hasExternalReference ?sensor ; ref:hasTimeseriesId ?sid .
  }
  OPTIONAL { ?sensor rdfs:label ?label . }
}

